package lrucache

import "testing"

func TestLRUBasic(t *testing.T) {
	cache := NewLRUCache(2)
	cache.Put(1, 10)
	cache.Put(2, 20)
	if v, ok := cache.Get(1); !ok || v != 10 {
		t.Fatalf("want 10 got %d", v)
	}
}

func TestLRUEviction(t *testing.T) {
	cache := NewLRUCache(2)
	cache.Put(1, 10)
	cache.Put(2, 20)
	cache.Put(3, 30) // evicts key 1
	if _, ok := cache.Get(1); ok {
		t.Fatal("key 1 should have been evicted")
	}
	if v, ok := cache.Get(3); !ok || v != 30 {
		t.Fatalf("want 30 got %d", v)
	}
}

func TestLRUUpdateKeepsRecent(t *testing.T) {
	cache := NewLRUCache(2)
	cache.Put(1, 10)
	cache.Put(2, 20)
	cache.Put(1, 100) // update makes 1 most recent
	cache.Put(3, 30)  // evicts key 2 (least recent)
	if _, ok := cache.Get(2); ok {
		t.Fatal("key 2 should have been evicted")
	}
	if v, ok := cache.Get(1); !ok || v != 100 {
		t.Fatalf("want 100 got %d", v)
	}
}

func TestLRUGetPromotes(t *testing.T) {
	cache := NewLRUCache(2)
	cache.Put(1, 10)
	cache.Put(2, 20)
	cache.Get(1)     // promotes 1 to most recent
	cache.Put(3, 30) // evicts key 2
	if _, ok := cache.Get(2); ok {
		t.Fatal("key 2 should have been evicted")
	}
}

func TestLRUMiss(t *testing.T) {
	cache := NewLRUCache(2)
	if _, ok := cache.Get(99); ok {
		t.Fatal("should miss on empty cache")
	}
}

